  /* ── VERIFY V7 PROPERTY KIND ── */
  verify_v6s_legal_body_kind: 'לפני קניית {{noun}} חשוב לברר שלושה נושאים: על שם מי רשום הנכס, האם חלות עליו מגבלות בתוקף ובאיזה מצב נמצא התיעוד הרשמי של הבניין.\nאנחנו בוחנים את הרשומות שמצאנו לפי התאריכים המדויקים שלהן, כי נסח ישן לא תמיד משקף את המצב הנוכחי.\nלהלן תראו מה מאושר רשמית, מה השתנה עם הזמן ואיזה מידע יש לעדכן לפני העסקה.',
  verify_v6s_intro_body_kind: 'הסיפור של הבניין הזה לא מתחיל במראה שלו היום. במסמכים הרשמיים יש חומרי תכנון והחלטות מתקופות שונות, שמראים איך הפרויקט התפתח לאורך השנים.\nבחנו את החומרים האלה כדי להבין מה תוכנן בהתחלה, מה השתנה אחר כך, אילו שינויים אושרו ומה ידוע לנו על מצב הבניין כיום.\nלהלן נציג הכול לפי הסדר, ונתמקד במיוחד בנושאים שבאמת חשובים לפני קניית {{noun}}.',
  verify_v6s_materials_body_kind: 'החומרים המצוינים במסמכי הפרויקט עוזרים להבין מה תוכנן. כדי להעריך את מצבם בפועל, עדיף לראות את הבניין באופן אישי.\nמומלץ לאמת את הפרטים מול הבעלים או, אם לפרויקט יש נציג מכירות, ישירות מולו. שימו לב במיוחד לחזית, לחלונות, לשטחים המשותפים, למערכות ההנדסה ולמצב המסירה ({{noun}}).',
  verify_v3_reg_unit_mortgage_kind: 'משכנתה {{noun}}',
  verify_v3_reg_parcel_security_note_kind: 'רשום על המגרש או הבניין ולא רק {{noun}}. לפני התשלום שאלו את היזם ואת המלווה איך הנכס ישוחרר ממנו.',
  verify_co_company_scope_note_kind: 'הרישום הזה הוא על החברה עצמה. זו אינה משכנתה {{noun}}, ושום דבר כאן אינו מראה שהוא חל על הנכס.',
  vrx_identity_title_kind: 'לאיזה נכס מתייחסות הרשומות',
  verify_v6s_pending_body_kind: 'ברשומות הרשמיות מופיעים נושאים שעדיין לא אושרה לגביהם החלטה סופית. אין בכך כשלעצמו כדי לומר שיש בפרויקט בעיה. בחינת שינויי תכנון במהלך הבנייה יכולה להיות גם הליך רגיל.\nחשוב להבין במה בדיוק עוסק כל שינוי והאם הוא עשוי להשפיע על הבניין או על הנכס שלכם.\nלהלן נסביר כל נושא בנפרד ונציג גם את המסמך הרשמי הרלוונטי.',
  verify_v7_market_kind_none: 'לא נמצא מדגם שוק בר השוואה לסוג נכס זה ({{kind}}), ולכן הדוח אינו מציג הערכת מחיר. מחירי דירות אינם השוואה תקפה עבורו.',
